15	export function MarketingHeader() {
16	  const pathname = usePathname();
17	  const [open, setOpen] = useState(false);
18	  const [scrolled, setScrolled] = useState(false);
19	
20	  useEffect(() => {
21	    const onScroll = () => setScrolled(window.scrollY > 8);
22	    onScroll();
23	    window.addEventListener("scroll", onScroll, { passive: true });
24	    return () => window.removeEventListener("scroll", onScroll);
25	  }, []);
26	
27	  // Close the mobile menu whenever the route changes.
28	  useEffect(() => setOpen(false), [pathname]);
29	
30	  return (
31	    <header
32	      className={`sticky top-0 z-50 border-b transition-colors duration-300 ${
33	        scrolled
34	          ? "border-white/[0.06] bg-navy-950/80 backdrop-blur-xl"
35	          : "border-transparent bg-transparent"
36	      }`}
37	    >
38	      <div className="mx-auto flex h-[68px] max-w-6xl items-center justify-between px-5 sm:px-6">
39	        <NxLogo id="hdr" size={42} />
40	
41	        <nav className="hidden items-center gap-1 md:flex">
42	          {NAV.map((item) => {
43	            const active = pathname === item.href;
44	            return (
45	              <Link
46	                key={item.href}
47	                href={item.href}
48	                className={`rounded-lg px-3 py-2 text-sm font-medium transition-colors ${
49	                  active ? "text-white" : "text-slate-400 hover:text-white"
50	                }`}
51	              >
52	                {item.label}
53	              </Link>
54	            );
55	          })}
56	        </nav>
57	
58	        <div className="hidden items-center gap-2 md:flex">
59	          <Link href="/login" className="btn-ghost">
60	            Log in
61	          </Link>
62	          <Link href="/register" className="btn-primary">
63	            Get Started
64	          </Link>
65	        </div>
66	
67	        <button
68	          className="btn-ghost rounded-lg p-2 md:hidden"
69	          aria-label="Toggle menu"
70	          aria-expanded={open}
71	          onClick={() => setOpen((v) => !v)}
72	        >
73	          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
74	            {open ? <path d="M6 6l12 12M18 6 6 18" /> : <path d="M4 7h16M4 12h16M4 17h16" />}
75	          </svg>
76	        </button>
77	      </div>
78	
79	      {/* Mobile menu */}
80	      {open && (
81	        <div className="border-t border-white/[0.06] bg-navy-950/95 backdrop-blur-xl md:hidden">
82	          <nav className="mx-auto flex max-w-6xl flex-col gap-1 px-5 py-4">
83	            {NAV.map((item) => (
84	              <Link
85	                key={item.href}
86	                href={item.href}
87	                className="rounded-lg px-3 py-2.5 text-sm font-medium text-slate-300 hover:bg-white/[0.05] hover:text-white"
88	              >
89	                {item.label}
90	              </Link>
91	            ))}
92	            <div className="mt-2 flex flex-col gap-2 border-t border-white/[0.06] pt-3">
93	              <Link href="/login" className="btn-secondary w-full">
94	                Log in
95	              </Link>
96	              <Link href="/register" className="btn-primary w-full">
97	                Get Started
98	              </Link>
99	            </div>
100	          </nav>
101	        </div>
102	      )}
103	    </header>
104	  );
105	}
