46	/** Product + offers for the pricing page. */
47	export function ProductJsonLd({
48	  plans,
49	}: {
50	  plans: Array<{ name: string; priceCents: number }>;
51	}) {
52	  const offers = plans.map((p) => ({
53	    "@type": "Offer",
54	    name: `${p.name} VPS`,
55	    price: (p.priceCents / 100).toFixed(2),
56	    priceCurrency: "USD",
57	    availability: "https://schema.org/InStock",
58	    url: `${APP_URL}/pricing`,
59	  }));
60	  return (
61	    <JsonLd
62	      data={{
63	        "@context": "https://schema.org",
64	        "@type": "Product",
65	        name: "Nxeon Cloud VPS",
66	        description:
67	          "NVMe cloud VPS with full root access, one-click apps, game servers, and an optional dedicated IPv4.",
68	        brand: { "@type": "Brand", name: "Nxeon" },
69	        offers: {
70	          "@type": "AggregateOffer",
71	          priceCurrency: "USD",
72	          lowPrice: plans.length ? (Math.min(...plans.map((p) => p.priceCents)) / 100).toFixed(2) : undefined,
73	          offerCount: plans.length,
74	          offers,
75	        },
76	      }}
77	    />
78	  );
79	}
