72	// Inline markdown → HTML. Code spans are protected first so their contents are
73	// never re-processed as bold/links.
74	function inline(text) {
75	  const codes = [];
76	  let s = esc(text).replace(/`([^`]+)`/g, (_, c) => {
77	    codes.push(c);
78	    return `${codes.length - 1}`;
79	  });
80	  s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
81	  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_, t, u) => {
82	    const safe = u.startsWith("http") || u.startsWith("/") || u.startsWith("#") ? u : "#";
83	    return `<a href="${safe}"${safe.startsWith("http") ? ' target="_blank" rel="noopener"' : ""}>${t}</a>`;
84	  });
85	  // Bare URLs (not already inside an href).
86	  s = s.replace(/(^|[\s(])((?:https?:\/\/)[^\s<)]+)/g, (m, pre, url) =>
87	    `${pre}<a href="${url}" target="_blank" rel="noopener">${url.replace(/^https?:\/\//, "")}</a>`
88	  );
