103	// Render a run of body lines (no ## headings) into block HTML.
104	function renderBody(lines) {
105	  const out = [];
106	  let i = 0;
107	  while (i < lines.length) {
108	    let line = lines[i];
109	
110	    if (!line.trim()) { i++; continue; }
111	
112	    // Horizontal rule / section divider — swallow (## already delimits sections).
113	    if (/^---+$/.test(line.trim())) { i++; continue; }
114	
115	    // Fenced code block.
116	    if (/^```/.test(line.trim())) {
117	      const buf = [];
118	      i++;
119	      while (i < lines.length && !/^```/.test(lines[i].trim())) { buf.push(lines[i]); i++; }
120	      i++;
121	      out.push(`<pre class="codeblock"><code>${esc(buf.join("\n"))}</code></pre>`);
122	      continue;
123	    }
124	
125	    // Blockquote (one or more consecutive `>` lines).
126	    if (/^>\s?/.test(line)) {
127	      const buf = [];
128	      while (i < lines.length && /^>\s?/.test(lines[i])) {
129	        buf.push(lines[i].replace(/^>\s?/, ""));
