136	    // h3
137	    if (/^###\s+/.test(line)) {
138	      out.push(`<h3>${inline(line.replace(/^###\s+/, ""))}</h3>`);
139	      i++;
140	      continue;
141	    }
142	
143	    // Table (header row followed by a |---| separator).
144	    if (line.trim().startsWith("|") && i + 1 < lines.length && /^\s*\|?[\s:|-]+\|?\s*$/.test(lines[i + 1]) && lines[i + 1].includes("-")) {
145	      const cells = (r) => r.trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim());
146	      const head = cells(line);
147	      i += 2;
148	      const rows = [];
149	      while (i < lines.length && lines[i].trim().startsWith("|")) {
150	        rows.push(cells(lines[i]));
151	        i++;
152	      }
