154	      const body = rows
155	        .map((r) => `<tr>${r.map((c) => `<td>${inline(c)}</td>`).join("")}</tr>`)
156	        .join("");
157	      out.push(`<div class="tablewrap"><table><thead><tr>${th}</tr></thead><tbody>${body}</tbody></table></div>`);
158	      continue;
159	    }
160	
161	    // Unordered list (with wrapped continuation lines).
162	    if (/^\s*[-*]\s+/.test(line)) {
163	      const items = [];
164	      while (i < lines.length && (/^\s*[-*]\s+/.test(lines[i]) || (items.length && lines[i].trim() && !/^#{1,3}\s/.test(lines[i]) && !lines[i].trim().startsWith("|")))) {
165	        if (/^\s*[-*]\s+/.test(lines[i])) {
166	          items.push(lines[i].replace(/^\s*[-*]\s+/, ""));
167	        } else {
168	          items[items.length - 1] += " " + lines[i].trim();
169	        }
170	        i++;
171	      }
172	      out.push(`<ul>${items.map((t) => `<li>${inline(t)}</li>`).join("")}</ul>`);
173	      continue;
174	    }
175	
176	    // Paragraph (gather until blank / block boundary).
177	    const para = [line];
178	    i++;
179	    while (i < lines.length && lines[i].trim() && !/^#{1,3}\s/.test(lines[i]) && !/^\s*[-*]\s+/.test(lines[i]) && !lines[i].trim().startsWith("|") && !/^```/.test(lines[i].trim()) && !/^---+$/.test(lines[i].trim())) {
180	      para.push(lines[i]);
181	      i++;
182	    }
183	    out.push(`<p>${inline(para.join(" "))}</p>`);
184	  }
185	  return out.join("\n");
186	}
