import { db } from "@/lib/db";
import type { BlogPost } from "@prisma/client";

export const APP_URL = process.env.APP_URL ?? "https://revsports.ca";

/* ----------------------------------------------------------------------------
 * Fetch helpers
 * ------------------------------------------------------------------------- */

/** Published posts, newest first — for the public blog index. */
export function getPublishedPosts(): Promise<BlogPost[]> {
  return db.blogPost.findMany({
    where: { published: true },
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
  });
}

/** A single published post by slug, or null (drives notFound() on the page). */
export function getPublishedPost(slug: string): Promise<BlogPost | null> {
  return db.blogPost.findFirst({ where: { slug, published: true } });
}

/** Every post regardless of status, newest edit first — for the admin editor. */
export function getAllPosts(): Promise<BlogPost[]> {
  return db.blogPost.findMany({ orderBy: { updatedAt: "desc" } });
}

/** Look up any post by id (admin edit form). */
export function getPostById(id: string): Promise<BlogPost | null> {
  return db.blogPost.findUnique({ where: { id } });
}

/* ----------------------------------------------------------------------------
 * Formatting
 * ------------------------------------------------------------------------- */

export function formatDate(d: Date | string | null | undefined): string {
  if (!d) return "";
  const date = typeof d === "string" ? new Date(d) : d;
  return date.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
}

/** Rough read-time estimate from the raw markdown body. */
export function readMinutes(body: string): number {
  const words = body.trim().split(/\s+/).filter(Boolean).length;
  return Math.max(1, Math.round(words / 200));
}

/* ----------------------------------------------------------------------------
 * Tiny, self-contained markdown → HTML renderer.
 *
 * No external dependency. Handles: # / ## / ### headings, **bold**, `code`,
 * fenced ``` code blocks, - / * and 1. lists, [links](url), and blank-line
 * separated paragraphs. HTML is escaped BEFORE any markdown is applied, and
 * inline code spans are protected so their contents are never re-processed.
 * Output carries Tailwind classes so it reads well on the dark theme (there is
 * no typography plugin installed).
 * ------------------------------------------------------------------------- */

function esc(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

const CLS = {
  h1: "mt-10 mb-4 text-3xl font-bold tracking-tight text-white",
  h2: "mt-10 mb-3 text-2xl font-bold tracking-tight text-white",
  h3: "mt-8 mb-2 text-xl font-semibold text-white",
  p: "mb-4 leading-relaxed text-slate-300",
  ul: "mb-5 list-disc space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
  ol: "mb-5 list-decimal space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
  li: "leading-relaxed",
  a: "text-brand-300 underline decoration-brand-300/40 underline-offset-2 hover:text-brand-200",
  code: "rounded-md border border-white/10 bg-white/[0.06] px-1.5 py-0.5 font-mono text-[0.85em] text-brand-200",
  pre: "mb-5 overflow-x-auto rounded-xl border border-white/10 bg-navy-950/80 p-4 font-mono text-[13px] leading-relaxed text-slate-200",
};

/** Inline markdown for a single run of text. */
function inline(text: string): string {
  const codes: string[] = [];
  // Protect inline code first.
  let s = esc(text).replace(/`([^`]+)`/g, (_m, c: string) => {
    codes.push(c);
    return `�${codes.length - 1}�`;
  });
  // Bold.
  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong class="font-semibold text-white">$1</strong>');
  // Links [text](url) — only http(s), root-relative, or anchors are allowed.
  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, t: string, u: string) => {
    const safe = /^(https?:\/\/|\/|#)/.test(u) ? u : "#";
    const ext = safe.startsWith("http");
    return `<a class="${CLS.a}" href="${safe}"${ext ? ' target="_blank" rel="noopener noreferrer"' : ""}>${t}</a>`;
  });
  // Restore inline code.
  s = s.replace(/�(\d+)�/g, (_m, i: string) => `<code class="${CLS.code}">${codes[+i]}</code>`);
  return s;
}

export function renderMarkdown(md: string): string {
  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
  const out: string[] = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    // Blank line — skip.
    if (!line.trim()) { i++; continue; }

    // Horizontal rule.
    if (/^---+$/.test(line.trim())) {
      out.push('<hr class="my-8 border-white/[0.08]" />');
      i++;
      continue;
    }

    // Fenced code block.
    if (/^```/.test(line.trim())) {
      const buf: string[] = [];
      i++;
      while (i < lines.length && !/^```/.test(lines[i].trim())) { buf.push(lines[i]); i++; }
      i++; // closing fence
      out.push(`<pre class="${CLS.pre}"><code>${esc(buf.join("\n"))}</code></pre>`);
      continue;
    }

    // Headings.
    if (/^###\s+/.test(line)) { out.push(`<h3 class="${CLS.h3}">${inline(line.replace(/^###\s+/, ""))}</h3>`); i++; continue; }
    if (/^##\s+/.test(line))  { out.push(`<h2 class="${CLS.h2}">${inline(line.replace(/^##\s+/, ""))}</h2>`);  i++; continue; }
    if (/^#\s+/.test(line))   { out.push(`<h1 class="${CLS.h1}">${inline(line.replace(/^#\s+/, ""))}</h1>`);   i++; continue; }

    // Ordered list.
    if (/^\s*\d+\.\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*\d+\.\s+/, ""));
        i++;
      }
      out.push(`<ol class="${CLS.ol}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ol>`);
      continue;
    }

    // Unordered list.
    if (/^\s*[-*]\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*[-*]\s+/, ""));
        i++;
      }
      out.push(`<ul class="${CLS.ul}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ul>`);
      continue;
    }

    // Paragraph — gather until a blank line or block boundary.
    const para = [line];
    i++;
    while (
      i < lines.length &&
      lines[i].trim() &&
      !/^#{1,3}\s/.test(lines[i]) &&
      !/^\s*[-*]\s+/.test(lines[i]) &&
      !/^\s*\d+\.\s+/.test(lines[i]) &&
      !/^```/.test(lines[i].trim()) &&
      !/^---+$/.test(lines[i].trim())
    ) {
      para.push(lines[i]);
      i++;
    }
    out.push(`<p class="${CLS.p}">${inline(para.join(" "))}</p>`);
  }

  return out.join("\n");
}

