  seoTitle: z.string().max(160).optional(),
  seoDescription: z.string().max(320).optional(),
  published: z.boolean(),
});

/** Create or update a blog post. Wired to a <form> via useActionState. */
export async function saveBlogPost(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");

  const parsed = schema.safeParse({
    id: (formData.get("id") as string) || undefined,
    slug: formData.get("slug"),
    title: formData.get("title"),
    excerpt: formData.get("excerpt") ?? "",
    body: formData.get("body") ?? "",
    coverEmoji: (formData.get("coverEmoji") as string) || undefined,
    tags: formData.get("tags") ?? "",
    category: (formData.get("category") as string) || undefined,
    author: (formData.get("author") as string) || undefined,
    seoTitle: (formData.get("seoTitle") as string) || undefined,
    seoDescription: (formData.get("seoDescription") as string) || undefined,
    published: formData.get("published") === "on" || formData.get("published") === "true",
  });

  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid post." };
  }

  const { id, tags, published, coverEmoji, seoTitle, seoDescription, ...rest } = parsed.data;
  const tagList = tags
    .split(",")
    .map((t) => t.trim())
    .filter(Boolean);

  const data = {
    ...rest,
    tags: tagList,
    coverEmoji: coverEmoji || null,
    seoTitle: seoTitle || null,
    seoDescription: seoDescription || null,
    published,
  };

  // Guard against slug collisions on a different row.
  const clash = await db.blogPost.findUnique({ where: { slug: data.slug } });
  if (clash && clash.id !== id) {
    return { error: `Another post already uses the slug "${data.slug}".` };
  }

  try {
    if (id) {
      const existing = await db.blogPost.findUnique({ where: { id } });
      if (!existing) return { error: "Post not found." };
      await db.blogPost.update({
        where: { id },
        data: {
          ...data,
          // Stamp publishedAt the first time it goes live; keep it thereafter.
          publishedAt: published ? existing.publishedAt ?? new Date() : existing.publishedAt,
        },
      });
    } else {
      await db.blogPost.create({
        data: { ...data, publishedAt: published ? new Date() : null },
      });
    }
  } catch (err) {
    await logEvent("error", "blog.save", { message: String(err), slug: data.slug });
    return { error: "Could not save the post. Please try again." };
  }

  revalidatePath("/admin/blog");
  revalidatePath("/blog");
  revalidatePath(`/blog/${data.slug}`);
  redirect("/admin/blog");
}

/** Flip a post between draft and published. */
export async function toggleBlogPublish(id: string): Promise<ActionState> {
  await requireArea("platform");
  const post = await db.blogPost.findUnique({ where: { id } });
  if (!post) return { error: "Post not found." };

  const next = !post.published;
  await db.blogPost.update({
    where: { id },
    data: {
      published: next,
      publishedAt: next ? post.publishedAt ?? new Date() : post.publishedAt,
    },
  });

  revalidatePath("/admin/blog");
  revalidatePath("/blog");
  revalidatePath(`/blog/${post.slug}`);
  return {};
}

/** Permanently delete a post. */
export async function deleteBlogPost(id: string): Promise<ActionState> {
  await requireArea("platform");
  const post = await db.blogPost.findUnique({ where: { id } });
  if (!post) return { error: "Post not found." };

  await db.blogPost.delete({ where: { id } });

  revalidatePath("/admin/blog");
  revalidatePath("/blog");
  revalidatePath(`/blog/${post.slug}`);
  return {};
}

