            <div className="mb-8 text-sm">
              <Link href="/blog" className="text-slate-400 transition-colors hover:text-white">
                ← Back to all posts
              </Link>
            </div>

            {/* Header */}
            <div className="mb-3 flex flex-wrap items-center gap-2 text-xs text-slate-400">
              <span className="rounded-full border border-brand-500/40 bg-brand-500/10 px-2.5 py-0.5 font-medium text-brand-300">
                {post.category}
              </span>
              <span>{formatDate(published)}</span>
              <span aria-hidden>·</span>
              <span>{readMinutes(post.body)} min read</span>
            </div>

            {post.coverEmoji && (
              <div className="mb-5 text-6xl" aria-hidden>
                {post.coverEmoji}
              </div>
            )}

            <h1 className="text-3xl font-extrabold tracking-tight sm:text-4xl">{post.title}</h1>
            {post.excerpt && <p className="mt-4 text-lg text-slate-400">{post.excerpt}</p>}

            <div className="mt-6 flex items-center gap-2 border-b border-white/[0.08] pb-8 text-sm text-slate-500">
              <span className="flex h-7 w-7 items-center justify-center rounded-full bg-gradient-to-br from-accent-blue to-brand-500 text-[11px] font-bold text-white">
                N
              </span>
              By {post.author}
            </div>
          </div>

          {/* Body */}
          <div className="relative mx-auto max-w-3xl px-5 py-10 sm:px-6">
            <div dangerouslySetInnerHTML={{ __html: html }} />

            {post.tags.length > 0 && (
              <div className="mt-10 flex flex-wrap gap-2 border-t border-white/[0.08] pt-6">
                {post.tags.map((t) => (
                  <span
                    key={t}
                    className="rounded-full border border-white/10 bg-white/[0.04] px-3 py-1 text-xs text-slate-400"
                  >
                    #{t}
                  </span>
                ))}
              </div>
            )}
          </div>
