import type { Metadata } from "next";
import { MarketingHeader } from "@/components/marketing/MarketingHeader";
import { MarketingFooter } from "@/components/marketing/MarketingFooter";

const APP_URL = process.env.APP_URL ?? "https://revsports.ca";

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "System Status",
  description: "Live operational status of the Nxeon platform — web dashboard, provisioning, networking and backups.",
  alternates: { canonical: "/status" },
  openGraph: {
    type: "website",
    title: "Nxeon System Status",
    description: "Live operational status of the Nxeon platform.",
    url: `${APP_URL}/status`,
  },
};

type Health = "operational" | "degraded" | "maintenance" | "outage";

const COMPONENTS: { name: string; description: string; status: Health }[] = [
  { name: "Web & Dashboard", description: "Marketing site, customer portal and admin console", status: "operational" },
  { name: "Provisioning", description: "Server creation, reinstall, resize and power actions", status: "operational" },
  { name: "Network", description: "Port forwarding, dedicated IPs and edge connectivity", status: "operational" },
  { name: "Backups", description: "Scheduled snapshots and restore pipeline", status: "operational" },
];

const STATUS_META: Record<Health, { label: string; dot: string; text: string; pulse?: boolean }> = {
  operational: { label: "Operational", dot: "bg-emerald-400", text: "text-emerald-400", pulse: true },
  degraded: { label: "Degraded performance", dot: "bg-amber-400", text: "text-amber-400", pulse: true },
  maintenance: { label: "Under maintenance", dot: "bg-brand-400", text: "text-brand-300" },
  outage: { label: "Outage", dot: "bg-red-400", text: "text-red-400", pulse: true },
};

// 90-day history strip — all green in this placeholder. Real monitoring wires in later.
const HISTORY = Array.from({ length: 90 });

export default function StatusPage() {
  const allOk = COMPONENTS.every((c) => c.status === "operational");
  const now = new Date();
  const checkedAt = now.toLocaleString("en-US", {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone: "UTC",
  });

  return (
    <div className="flex min-h-screen flex-col">
      <MarketingHeader />
      <main className="flex-1">
        <section className="relative overflow-hidden">
          <div
            className="pointer-events-none absolute inset-x-0 top-0 h-[320px] opacity-70"
            style={{ backgroundImage: "radial-gradient(ellipse 55% 50% at 50% 0%, rgba(16,185,129,0.12), transparent)" }}
          />
          <div className="relative mx-auto max-w-4xl px-5 pt-16 sm:px-6">
            <p className="section-label mb-3">System Status</p>

            {/* Overall banner */}
            <div className="card flex items-center gap-4 border-emerald-500/20 bg-emerald-500/[0.06]">
              <span className="relative flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-emerald-500/15">
                <span className="h-3 w-3 rounded-full bg-emerald-400 animate-pulse-dot" />
              </span>
              <div>
                <h1 className="text-xl font-bold tracking-tight text-white">
                  {allOk ? "All systems operational" : "Some systems are affected"}
                </h1>
                <p className="mt-0.5 text-sm text-slate-400">
                  Last checked {checkedAt} UTC
                </p>
              </div>
            </div>
          </div>
        </section>

        {/* Components */}
        <section className="mx-auto max-w-4xl px-5 py-10 sm:px-6">
          <h2 className="section-label mb-3">Components</h2>
          <div className="card divide-y divide-white/[0.06] p-0">
            {COMPONENTS.map((c) => {
              const meta = STATUS_META[c.status];
              return (
                <div key={c.name} className="flex items-center justify-between gap-4 px-6 py-5">
                  <div>
                    <p className="font-medium text-white">{c.name}</p>
                    <p className="mt-0.5 text-sm text-slate-400">{c.description}</p>
                  </div>
                  <span className={`inline-flex shrink-0 items-center gap-2 text-sm font-medium ${meta.text}`}>
                    <span className={`h-2.5 w-2.5 rounded-full ${meta.dot} ${meta.pulse ? "animate-pulse-dot" : ""}`} />
                    {meta.label}
                  </span>
                </div>
              );
            })}
          </div>
        </section>

        {/* 90-day uptime strip */}
        <section className="mx-auto max-w-4xl px-5 pb-10 sm:px-6">
          <div className="card">
            <div className="flex items-center justify-between">
              <h2 className="section-label">Uptime — last 90 days</h2>
              <span className="text-sm font-semibold text-emerald-400">100.00%</span>
            </div>
            <div className="mt-4 flex items-end gap-[3px]">
              {HISTORY.map((_, i) => (
                <span
                  key={i}
                  title="Operational"
