"use client";

import Link from "next/link";
import { useActionState, useState, useTransition } from "react";
import { saveBlogPost, toggleBlogPublish, deleteBlogPost } from "@/lib/actions-blog";

type Post = {
  id: string;
  slug: string;
  title: string;
  excerpt: string;
  body: string;
  coverEmoji: string | null;
  tags: string[];
  author: string;
  category: string;
  published: boolean;
  seoTitle: string | null;
  seoDescription: string | null;
};

/** Create / edit form. Pass a `post` to edit, omit to create. */
export function BlogEditor({ post }: { post?: Post }) {
  const [state, action, pending] = useActionState(saveBlogPost, {});
  const editing = Boolean(post?.id);

  return (
    <form action={action} className="space-y-4">
      {post?.id && <input type="hidden" name="id" value={post.id} />}

      {state?.error && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {state.error}
        </div>
      )}

      <div className="grid gap-4 sm:grid-cols-2">
        <div className="sm:col-span-2">
          <label className="label">Title</label>
          <input className="input" name="title" defaultValue={post?.title} required maxLength={160} />
        </div>
        <div>
          <label className="label">Slug</label>
          <input
            className="input"
            name="slug"
            defaultValue={post?.slug}
            required
            pattern="[a-z0-9-]+"
            placeholder="how-to-set-up-a-minecraft-server"
          />
        </div>
        <div>
          <label className="label">Category</label>
          <input className="input" name="category" defaultValue={post?.category ?? "Guides"} required />
        </div>
        <div>
          <label className="label">Cover emoji</label>
          <input className="input" name="coverEmoji" defaultValue={post?.coverEmoji ?? ""} maxLength={8} placeholder="🎮" />
        </div>
        <div>
          <label className="label">Author</label>
          <input className="input" name="author" defaultValue={post?.author ?? "Nxeon"} required />
        </div>
        <div className="sm:col-span-2">
          <label className="label">Tags (comma separated)</label>
          <input className="input" name="tags" defaultValue={post?.tags?.join(", ") ?? ""} placeholder="vps, minecraft, tutorial" />
        </div>
      </div>

      <div>
        <label className="label">Excerpt</label>
        <textarea className="input min-h-[70px]" name="excerpt" defaultValue={post?.excerpt} maxLength={400} rows={2} />
      </div>

      <div>
        <label className="label">Body (markdown)</label>
        <textarea
          className="input min-h-[320px] font-mono text-[13px]"
          name="body"
          defaultValue={post?.body}
          rows={16}
          placeholder={"## Heading\n\nWrite the post in markdown. Supports **bold**, `code`, - lists, and [links](https://example.com)."}
        />
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <div>
          <label className="label">SEO title (optional)</label>
          <input className="input" name="seoTitle" defaultValue={post?.seoTitle ?? ""} maxLength={160} />
        </div>
        <div>
          <label className="label">SEO description (optional)</label>
          <input className="input" name="seoDescription" defaultValue={post?.seoDescription ?? ""} maxLength={320} />
        </div>
      </div>

      <div className="flex flex-wrap items-center justify-between gap-3 border-t border-white/[0.06] pt-4">
        <label className="flex items-center gap-2 text-sm text-slate-300">
          <input type="checkbox" name="published" defaultChecked={post?.published ?? false} />
          Published (visible on the public blog)
        </label>
        <div className="flex items-center gap-2">
          {editing && (
            <Link href="/admin/blog" className="btn-secondary">
              Cancel
            </Link>
          )}
          <button className="btn-primary" disabled={pending}>
            {pending ? "Saving…" : editing ? "Save changes" : "Create post"}
          </button>
        </div>
      </div>
    </form>
  );
}

/** Per-row publish toggle + delete for the posts table. */
export function BlogRowActions({ id, published }: { id: string; published: boolean }) {
  const [pending, start] = useTransition();
  const [confirming, setConfirming] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  return (
    <div className="flex items-center justify-end gap-2">
      {err && <span className="text-xs text-red-400">{err}</span>}

      <Link href={`/admin/blog?edit=${id}`} className="btn-secondary px-3 py-1.5 text-xs">
        Edit
      </Link>

      <button
        className="btn-secondary px-3 py-1.5 text-xs"
        disabled={pending}
        onClick={() =>
          start(async () => {
            setErr(null);
            const res = await toggleBlogPublish(id);
            if (res.error) setErr(res.error);
          })
        }
      >
        {published ? "Unpublish" : "Publish"}
      </button>

      {confirming ? (
        <>
          <button
            className="btn-danger px-3 py-1.5 text-xs"
            disabled={pending}
            onClick={() =>
              start(async () => {
                setErr(null);
                const res = await deleteBlogPost(id);
                if (res.error) {
                  setErr(res.error);
                  setConfirming(false);
                }
              })
            }
          >
            {pending ? "Deleting…" : "Confirm"}
          </button>
          <button className="btn-ghost px-2 py-1.5 text-xs" disabled={pending} onClick={() => setConfirming(false)}>
            Cancel
          </button>
        </>
      ) : (
        <button className="btn-danger px-3 py-1.5 text-xs" onClick={() => setConfirming(true)}>
          Delete
        </button>
      )}
    </div>
  );
}

import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, timeAgo } from "@/components/ui/primitives";
import { getAllPosts, getPostById } from "@/lib/blog";
import { BlogEditor, BlogRowActions } from "@/components/admin/BlogControls";

export const dynamic = "force-dynamic";

export default async function AdminBlog({
  searchParams,
}: {
  searchParams: Promise<{ edit?: string }>;
}) {
  await requireArea("platform");
  const { edit } = await searchParams;

  const posts = await getAllPosts();
  const editing = edit ? await getPostById(edit) : null;

  const published = posts.filter((p) => p.published).length;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Blog"
        sub={`${posts.length} post${posts.length === 1 ? "" : "s"} · ${published} published`}
      />

      {/* Editor */}
      <div className="card">
        <h2 className="section-label mb-4">{editing ? `Editing: ${editing.title}` : "New post"}</h2>
        <BlogEditor post={editing ?? undefined} />
      </div>

      {/* Posts table */}
      <div>
        <h2 className="section-label mb-2">All posts</h2>
        <div className="card overflow-x-auto p-0">
          <table className="table-shell">
            <thead>
              <tr>
                <th>Post</th>
                <th>Category</th>
                <th>Status</th>
                <th>Updated</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {posts.length === 0 && (
                <tr>
                  <td colSpan={5} className="py-10 text-center text-slate-500">
                    No posts yet — use the form above to write your first one.
                  </td>
                </tr>
              )}
              {posts.map((p) => (
                <tr key={p.id}>
                  <td>
                    <div className="flex items-center gap-2">
                      <span className="text-lg" aria-hidden>
                        {p.coverEmoji ?? "📝"}
                      </span>
                      <div className="min-w-0">
                        <p className="truncate font-medium text-white">{p.title}</p>
                        <p className="truncate text-xs text-slate-500">/blog/{p.slug}</p>
                      </div>
                    </div>
                  </td>
                  <td className="text-sm text-slate-400">{p.category}</td>
                  <td>
                    {p.published ? <Badge tone="green">published</Badge> : <Badge tone="slate">draft</Badge>}
                  </td>
                  <td className="text-xs text-slate-400">{timeAgo(p.updatedAt)}</td>
                  <td>
                    <BlogRowActions id={p.id} published={p.published} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <p className="text-xs text-slate-500">
        Posts render markdown (headings, <span className="font-mono">**bold**</span>,{" "}
        <span className="font-mono">`code`</span>, lists and links). Only published posts appear on{" "}
        <span className="font-mono">/blog</span>.
      </p>
    </div>
  );
}

